#include <iostream>

class Resource {};

class ClassB_Leaky {
    Resource* ptr1; // Allocated successfully
    Resource* ptr2; // Allocation fails
public:
    // If new Resource() for ptr2 throws, ptr1 leaks.
    ClassB_Leaky() try : ptr1(new Resource()), 
                         ptr2(new Resource()) { 
    } catch (...) {
        // Destructor ~ClassB_Leaky is NOT called.
        // ptr1 is never deleted.
        throw;
    }
    ~ClassB_Leaky() { 
        delete ptr1; delete ptr2; 
    }
};
